record.field:
for record in self:
    if record.x_depot_loaded_liters:
        record['x_temp_allowance_liters'] = round(record.x_depot_loaded_liters * 0.0025, 2)
    else:
        record['x_temp_allowance_liters'] = 0.0

for record in self:
    loaded = record.x_depot_loaded_liters or 0.0
    delivered = record.x_truck_meter_delivered_liters or 0.0
    allowance = record.x_temp_allowance_liters or 0.0
    if loaded and delivered:
        record['x_net_variance_liters'] = round(loaded - delivered - allowance, 2)
    else:
        record['x_net_variance_liters'] = 0.0

for record in self:
    variance = record.x_net_variance_liters or 0.0
    if variance > 50.0:
        record['x_leakage_status'] = 'leakage_alert'
    elif variance > 10.0:
        record['x_leakage_status'] = 'minor_variance'
    else:
        record['x_leakage_status'] = 'normal'

current_year = datetime.date.today().year
for record in self:
    if record.x_manufacture_year:
        record['x_vehicle_age'] = max(0, current_year - record.x_manufacture_year)
    else:
        record['x_vehicle_age'] = 0

for record in self:
    age = record.x_vehicle_age or 0
    classification = record.x_unit_classification or 'prime_mover'
    if classification == 'prime_mover':
        if age >= 18:
            record['x_replacement_policy_status'] = 'replace_due'
        elif age >= 17:
            record['x_replacement_policy_status'] = 'warning'
        else:
            record['x_replacement_policy_status'] = 'compliant'
    else:
        if age >= 15:
            record['x_replacement_policy_status'] = 'replace_due'
        elif age >= 14:
            record['x_replacement_policy_status'] = 'warning'
        else:
            record['x_replacement_policy_status'] = 'compliant'

today = datetime.date.today()
for record in self:
    if record.x_hazchem_expiry and record.x_defensive_driving_expiry and record.x_medical_fitness_expiry:
        record['x_hse_compliant'] = (
            record.x_hazchem_expiry >= today and
            record.x_defensive_driving_expiry >= today and
            record.x_medical_fitness_expiry >= today
        )
    else:
        record['x_hse_compliant'] = False

today = datetime.date.today()
warning_window = today + datetime.timedelta(days=30)
for record in self:
    has_certs = any([record.x_hazchem_expiry, record.x_defensive_driving_expiry, record.x_medical_fitness_expiry])
    if not has_certs:
        record['x_hse_status_badge'] = 'not_applicable'
    else:
        hazchem_ok = record.x_hazchem_expiry and record.x_hazchem_expiry >= today
        defensive_ok = record.x_defensive_driving_expiry and record.x_defensive_driving_expiry >= today
        medical_ok = record.x_medical_fitness_expiry and record.x_medical_fitness_expiry >= today
        if hazchem_ok and defensive_ok and medical_ok:
            expiring = any([
                record.x_hazchem_expiry <= warning_window,
                record.x_defensive_driving_expiry <= warning_window,
                record.x_medical_fitness_expiry <= warning_window,
            ])
            record['x_hse_status_badge'] = 'expiring_soon' if expiring else 'compliant'
        else:
            record['x_hse_status_badge'] = 'expired'
